{
  "schemaVersion": 1,
  "date": "2026-10-06",
  "interview": [
    {
      "id": "interview-01",
      "articleIds": [
        "2026-10-06-top-1"
      ],
      "question": "AI開発ツールの権限制御が効いていることを、どう確かめますか。",
      "answer": "設定を眺めるだけでなく、拒否ありとなしで同じ操作を比べます。この記事ではsandboxの自動許可を有効にし、環境変数を前置したtouchを試しています。permission_denialsとファイルの有無を合わせて見ます。ただし、一つのコマンドの結果なので、別の入口も個別に確かめる必要があります。"
    },
    {
      "id": "interview-02",
      "articleIds": [
        "2026-10-06-top-2"
      ],
      "question": "ユーザーごとに分離したクラウド開発環境を、どう構成しますか。",
      "answer": "ECSのタスクにcode-serverを置き、認証済みユーザーの環境へProxyで振り分けます。この記事では起動後のIPをDynamoDBへ登録し、WebSocketも中継します。ただし、タスクは保守で止まることがあるので、保存方法と寿命を決めます。画面が開いたことだけでは、運用の安定性までは判断できません。"
    },
    {
      "id": "interview-03",
      "articleIds": [
        "2026-10-06-top-3"
      ],
      "question": "AIエージェントからAWSを操作するとき、認証情報をどう管理しますか。",
      "answer": "長期キーはaws-vaultの暗号化ストアに置き、credential_processで一時情報を渡します。1PasswordはMFAの発行に使い、作業先のロールで権限を絞ります。ただし、切替後のキーはCLIのキャッシュに残るので、平文を一切残せない規則にはそのまま適合しません。保管と利用時の境界を分けて確認します。"
    },
    {
      "id": "interview-04",
      "articleIds": [
        "2026-10-06-top-4"
      ],
      "question": "AIで作った業務画面のデータ鮮度を、どう確認しますか。",
      "answer": "表示を信じる前に、元データを変えて反映の契機を比べます。Amazon Quickの例ではDirect Queryは再読込みで更新され、SPICEは取り込みの完了まで旧値でした。ただし、表示ごとにAthenaのクエリが走ります。更新頻度だけでなく閲覧数と費用を見て選び、画面の最終編集日をデータの更新時刻と混同しません。"
    },
    {
      "id": "interview-05",
      "articleIds": [
        "2026-10-06-top-5"
      ],
      "question": "入力内容を装飾するUIで、何を壊さないようにしますか。",
      "answer": "送る文字とカーソル位置を保ち、見た目だけを変えます。md-promptはprompt.editでdecorationsを足し、装飾計算を純関数でテストしています。ただし、長い貼り付けは編集イベントが出ない場合があり、コードのテストだけでは画面を保証できません。展開後の入力や端末の見え方も実際に確認します。"
    }
  ],
  "review": [
    {
      "id": "review-01",
      "question": "ログの終了理由だけでは、なぜ権限拒否を判断できませんか。",
      "points": {
        "zh": "max-turns表示轮数上限；要结合permission_denials和文件实际存在情况。",
        "ja": "max-turnsは回数上限です。permission_denialsとファイルの状態を合わせて判断します。"
      },
      "articleIds": [
        "2026-10-06-top-1"
      ]
    },
    {
      "id": "review-02",
      "question": "長期キーを暗号化しても、残る確認事項は何ですか。",
      "points": {
        "zh": "目标角色权限、MFA、临时key缓存和TTL；无平文要求需单独审查。",
        "ja": "ロール権限、MFA、一時キーのキャッシュと寿命です。平文保存禁止の範囲を別に確認します。"
      },
      "articleIds": [
        "2026-10-06-top-3"
      ]
    },
    {
      "id": "review-03",
      "question": "データと表示の更新を、どう区別して検証しますか。",
      "points": {
        "zh": "数据用增量/源查询比较，画面编辑日不当作鲜度；装饰测试和端末观察独立。",
        "ja": "追加行とソースの問い合わせを比べ、編集日を鮮度にしません。装飾の計算と端末観察も分けます。"
      },
      "articleIds": [
        "2026-10-06-top-4",
        "2026-10-06-top-5"
      ]
    }
  ]
}
